style.css:
@-moz-document url-prefix("https://chat.openai.com/") {
/* Full dark hacker background */
    body, html {
        background-color: #0d0d0d !important;
        color: #00ff99 !important;
    }

    /* Chat messages */
    .text-base, .prose {
        color: #ff00ff !important;
        text-shadow: 0 0 5px #ff00ff, 0 0 10px #ff00ff;
    }

    /* RGB glowing effect */
    .border, .rounded-md {
        border: 3px solid;
        animation: rgb-border 3s infinite linear;
    }

    @keyframes rgb-border {
        0% { border-color: red; }
        33% { border-color: lime; }
        66% { border-color: blue; }
        100% { border-color: red; }
    }

    /* Cyberpunk neon buttons */
    button, .btn {
        background: linear-gradient(90deg, #ff00ff, #00ffff) !important;
        color: black !important;
        font-weight: bold !important;
        border-radius: 5px !important;
        box-shadow: 0 0 5px #ff00ff, 0 0 10px #00ffff !important;
    }

    button:hover, .btn:hover {
        filter: brightness(1.2) !important;
    }
}
